/**
 * Wave H item 1 — the bundled example dataset.
 *
 * The empty upload screen offers "Try with example data". That button has no
 * file picker behind it: it fetches `public/samples/example-usage.xml`, a
 * synthetic one-year Green Button feed generated by
 * `scripts/generate-example-fixture.mjs` (see its header for the model), and
 * pushes it through EXACTLY the same parser as a real upload — there is no
 * second, privileged data path to keep working.
 *
 * Every failure mode is returned as a sentence, never thrown at the caller:
 * the button's whole job is to work for someone who has no export at all.
 */

/* Wave U — the example-data copy translates; lib code reads the module locale. */
import { t } from '@/i18n';
import {
  parseGreenButtonUsagePoints,
  combineUsagePointGroups,
  type DataPoint,
} from './energy';

/** Served from `public/` — same origin, no CORS, cached by the SW like any asset. */
export const EXAMPLE_DATA_URL = '/samples/example-usage.xml';

/** On-disk name, so the label can promise what the file is. */
export const EXAMPLE_DATA_FILENAME = 'example-usage.xml';

/** What the UI calls it — the "not real usage" promise, in the user's words. */
export const EXAMPLE_DATA_LABEL = 'Example data — not real usage';

export type ExampleLoad =
  | { ok: true; readings: DataPoint[] }
  | { ok: false; detail: string };

/**
 * Fetch + parse the bundled sample.
 *
 * `fetcher` is injectable so the parser path (and every failure path) is
 * testable without a network or a running server.
 */
export async function loadExampleReadings(
  fetcher: typeof fetch = fetch,
): Promise<ExampleLoad> {
  let text: string;
  try {
    const res = await fetcher(EXAMPLE_DATA_URL);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    text = await res.text();
  } catch (e) {
    return {
      ok: false,
      detail: t('example.downloadFail', {
        reason: String((e as Error)?.message ?? e),
      }),
    };
  }

  let readings: DataPoint[];
  try {
    readings = combineUsagePointGroups(parseGreenButtonUsagePoints(text));
  } catch (e) {
    return {
      ok: false,
      detail: t('example.parseFail', {
        reason: String((e as Error)?.message ?? e),
      }),
    };
  }

  if (readings.length === 0) {
    return {
      ok: false,
      detail: t('example.noReadings'),
    };
  }

  return { ok: true, readings };
}
